def copy_agreements(apps, schema_editor):
    """これまでの「課長との合意」を、新しい3段階に移す。

    合意を依頼したもの → 確認を依頼した。合意したもの → 確認も承認も済み（承認したレベルは本人の到達、
    評価は growth.ae_grade と同じ目安で求める）。コメントは承認のコメントに移す。
    """
    Goal = apps.get_model('genba', 'Goal')
    for g in Goal.objects.filter(agreement_requested_at__isnull=False):
        g.submitted_at = g.agreement_requested_at
        if g.agreed_on:
            g.confirmed_at, g.confirmed_by_id = g.agreement_requested_at, g.agreed_by_id
            g.approved_on, g.approved_by_id, g.approved_level = g.agreed_on, g.agreed_by_id, g.reached_level
            g.approved_grade = 'A' if (g.reached_level or 0) >= 4 or (g.reached_level == 3 and g.mentored) else (
                'B' if g.reached_level == 3 else 'C')
            g.approval_comment = g.agreement_comment
        g.save()


